# Use supervision for automatic restart
graph MySupervisor from supervisor {
    fn on_message(msg) { return msg }
}

graph UnreliableWorker {
    fn on_message(msg) {
        if msg == "crash" {
            raise "something went wrong"
        }
        return "ok: " + msg
    }
}

sup = spawn MySupervisor{}
worker = spawn UnreliableWorker{}
sup.supervise(worker)  # auto-restart on crash

# Worker restarts automatically after crash
sup.close()

